package queue

import (
	&quot;context&quot;
	&quot;sync&quot;
)

type Queue[T any] struct {
	size    int
	buf     []*T
	head    int
	tail    int
	count   int
	changed *sync.Cond
}

func NewQueue[T any](size int) *Queue[T] {
	mu := &amp;sync.Mutex{}
	return &amp;Queue[T]{
		size:    size,
		buf:     make([]*T, size),
		head:    0,
		tail:    0,
		count:   0,
		changed: sync.NewCond(mu),
	}
}

&#47;&#47; Add one item to it&#39;s tail
func (q *Queue[T]) Add(ctx context.Context, v *T) error {
	q.changed.L.Lock()
	defer q.changed.L.Unlock()
	for q.count &gt;= q.size {
		q.changed.Wait()
	}
	q.buf[q.tail] = v
	q.tail = (q.tail + 1) % q.size
	q.count++
	q.changed.Signal()
	return nil
}

&#47;&#47; Pop one item from it&#39;s head
func (q *Queue[T]) Pop(ctx context.Context) (*T, error) {
	q.changed.L.Lock()
	defer q.changed.L.Unlock()
	for q.count == 0 {
		q.changed.Wait()
	}
	v := q.buf[q.head]
	q.buf[q.head] = nil
	q.head = (q.head + 1) % q.size
	q.count--
	q.changed.Signal()
	return v, nil
}
